NotebookLoader.register({"id":"messaging-events","title":"Messaging & Event-Driven Systems","category":"Software engineering","status":"ready","description":"22 lessons, three stage projects and a locally runnable practice kit covering reliable asynchronous workflows from messages to recovery.","level":"Foundations → intermediate practice with optional systems labs","prerequisites":["Basic Python and SQL transactions for the local exercises.","Python 3.11+ for the offline lab. No cloud account, payment method or broker is required."],"outcomes":["Choose queues, subscriptions and logs from delivery requirements.","Explain publisher confirms, consumer acknowledgements and uncertain outcomes.","Implement transactional outbox and durable duplicate-safe projections locally.","Design bounded retry, quarantine, ordering and compatible schema contracts.","Review replay, authorization, observability and multi-store recovery boundaries."],"setup":["Download the practice bundle and extract its flat files together.","From its folder run python event_lab.py, then python -m unittest -v test_event_lab.py.","Read README.md and workbook.md before optional external tooling. The verified baseline is local only."],"nextSteps":["Connect one real broker and test reconnect, persistence and denied access with synthetic data.","Connect this work to the full-stack journey. Record which integration tests you ran and which still need a live environment."],"sources":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber"},{"title":"CloudEvents specification","url":"https://cloudevents.io/"},{"title":"Azure competing consumers","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/competing-consumers"},{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/"},{"title":"RabbitMQ acknowledgements and confirms","url":"https://www.rabbitmq.com/docs/confirms"},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability"},{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos"},{"title":"RabbitMQ dead-letter exchanges","url":"https://www.rabbitmq.com/docs/dlx"},{"title":"Azure saga pattern","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/saga"}],"lessons":[{"id":"messages-events","title":"1. Messages, commands and events","takeaway":"Say whether the message requests work or reports a fact.","sections":[{"title":"Commands, events and completion","paragraphs":["A message is a transported payload. A command requests an action, such as GenerateExport, and needs an owner that can accept or reject it. An event reports something that already happened, such as ExportRequested. Event naming in past tense helps avoid confusing publication with completion. Asynchronous means sender and receiver can progress at different times; it does not mean work has succeeded."]},{"title":"Accepted versus ready","paragraphs":["Our notebook export example accepts a job, records its identifier, and later produces a file. ExportRequested and ExportCompleted are different facts. The UI can show Accepted while an export remains pending; it must not display Download ready merely because a broker accepted a payload."]}],"quiz":{"question":"Say whether the message requests work or reports a fact. Which decision follows?","options":["Keep accepted, running, completed and failed as separate observable states.","Treat the send operation as proof that the export exists.","Rename every request as a past-tense event to make it asynchronous."],"correct":0,"explanation":"A transport acknowledgement cannot establish the business outcome; only the responsible workflow can publish that fact."},"references":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"CloudEvents specification","url":"https://cloudevents.io/","section":"Specification; context attributes","reviewed":"2026-09-30","scope":"CloudEvents standard landing page; teaching envelopes are inspired by its vocabulary, not claimed as a conformant transport implementation."}],"stage":"foundation","exercise":{"prompt":"Classify CancelExport, ExportFailed and GetExportStatus. Write who owns each action and which event can truthfully follow a durable commit.","checks":["Classify all three names as command, event or query.","Name the export workflow owner and a truthful commit boundary for each fact."],"solution":"CancelExport requests cancellation and belongs to the export workflow owner; ExportFailed reports an observed failure; GetExportStatus queries that owner's recorded status. ExportRequested may follow a committed accepted job, while ExportCompleted follows durable completion. Cancellation can be rejected when the job has already completed.","solutionFormat":"prose"}},{"id":"topologies","title":"2. Queue, pub/sub and retained log","takeaway":"Choose a topology based on who must receive each message.","sections":[{"title":"Queues, subscriptions and logs","paragraphs":["A work queue distributes jobs among competing workers. Pub/sub delivers a copy to each logical subscription. A retained log lets consumers track positions and reread records while retention permits. These are distinct contracts even if one product supports several. Multiple workers on one subscription normally share work; they do not create independent audit and email subscribers."]},{"title":"Worker and subscriber counts","paragraphs":["Ten export jobs and two competing workers should yield ten completed jobs overall, not twenty. An audit subscription and a notification subscription each need their own copy of ExportCompleted. A reporting consumer on a retained log can rebuild its view from earlier records; a removed work-queue message cannot normally be replayed that way."]}],"quiz":{"question":"Choose a topology based on who must receive each message. Which decision follows?","options":["Use independent subscriptions for independent side effects.","Add an audit consumer to the same work queue and expect every event.","Use one shared consumer group for audit and notifications because both need every event."],"correct":0,"explanation":"Competing consumers divide work; independent subscriptions provide separate delivery histories."},"references":[{"title":"Azure competing consumers","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/competing-consumers","section":"Solution; issues and considerations","reviewed":"2026-09-30","scope":"Logical queue consumer pattern; not a guarantee for every broker."},{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."}],"stage":"foundation","exercise":{"prompt":"Sketch one export queue with two workers plus two completion subscriptions. Count expected deliveries for three jobs: three successful work executions, and three completion deliveries per subscription before considering redelivery.","checks":["Show one queue shared by two workers.","Count three deliveries per independent completion subscription and explain redelivery separately."],"solution":"One export queue distributes the three jobs between two workers, yielding three successful business executions. Two independent completion subscriptions each receive three facts before redelivery. Adding a second notification worker shares that subscription's work rather than producing another independent copy.","solutionFormat":"prose"},"diagram":{"title":"Work sharing versus independent subscribers","summary":"Workers share one job responsibility; audit and notification need separate event copies.","nodes":[{"id":"0","label":"Publisher","description":"Publishes a completion fact with stable event identity."},{"id":"1","label":"Audit subscription","description":"Owns audit delivery history."},{"id":"2","label":"Notification subscription","description":"Owns notification delivery history."},{"id":"3","label":"Notification worker A","description":"Competes for notification work."},{"id":"4","label":"Notification worker B","description":"Competes for notification work."}],"edges":[{"from":"0","to":"1","label":"independent copy"},{"from":"0","to":"2","label":"independent copy"},{"from":"2","to":"3","label":"assign work"},{"from":"2","to":"4","label":"assign other work"}],"steps":[{"title":"1. independent copy","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Owns audit delivery history."},{"title":"2. independent copy","activeNodes":["0","2"],"activeEdges":[1],"explanation":"Owns notification delivery history."},{"title":"3. assign work","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Competes for notification work."},{"title":"4. assign other work","activeNodes":["2","4"],"activeEdges":[3],"explanation":"Competes for notification work."}],"direction":"LR"}},{"id":"envelopes","title":"3. Envelope identity and correlation","takeaway":"Separate event identity from business identity and tracing.","sections":[{"title":"Event, job and correlation identity","paragraphs":["Give an event a stable ID, type, schema version, occurred time and source. A job ID identifies the export; an event ID identifies a particular fact; a correlation ID connects the user request and later work. Retrying publication must reuse the same event ID for that fact. A new correction is a new event, even if its business key matches."]},{"title":"Duplicate delivery of e-17","paragraphs":["A delivery of event e-17 concerning job j-4 can arrive twice. Deduplicating by e-17 avoids repeating its effect. Deduplicating all job j-4 events would accidentally discard ExportCompleted after ExportRequested. Timestamps aid investigation, but clock skew means they are not a universal ordering authority.","Run Python snippets from the extracted practice folder with event_lab.py present; JSON shows the strict v1 teaching envelope. No snippet connects to a broker."],"example":"{\n  \"id\": \"e-17\",\n  \"job_id\": \"j-4\",\n  \"type\": \"ExportRequested\",\n  \"version\": 1,\n  \"value\": 7\n}"},{"title":"Keep the sample envelope and the design distinct","paragraphs":["The JSON below is the small executable lab contract. It contains id, job_id, type, version and value only. The earlier discussion names additional production metadata; do not add those fields to the strict v1 parser and expect it to accept them. In the foundation sketch, write correlation and occurrence time beside the event. Lesson 14 explains how to introduce them as a versioned contract change.","The lab assumes event IDs are unique across its single event source. CloudEvents identifies an event by source plus id, so a multi-source inbox must preserve that source scope or use a documented globally unique ID policy."]}],"quiz":{"question":"Separate event identity from business identity and tracing. Which decision follows?","options":["Deduplicate the event ID within a named consumer.","Use a new random event ID each time the same event is retried.","Deduplicate on correlation ID so an entire workflow produces only one stored event."],"correct":0,"explanation":"Stable identity makes redelivery recognizable; correlation and business keys answer different questions."},"references":[{"title":"CloudEvents specification","url":"https://cloudevents.io/","section":"Specification; context attributes","reviewed":"2026-09-30","scope":"CloudEvents standard landing page; teaching envelopes are inspired by its vocabulary, not claimed as a conformant transport implementation."},{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"CloudEvents 1.0.2 event identity","url":"https://github.com/cloudevents/spec/blob/v1.0.2/cloudevents/spec.md","section":"Required attributes: id and source","reviewed":"2026-10-02","scope":"Source-plus-ID uniqueness; the teaching envelope is not a conformant CloudEvents implementation."}],"stage":"foundation","exercise":{"prompt":"Create two events for one job and one duplicate delivery. Identify the stable IDs and show which record your inbox suppresses. Keep real user emails and tokens out of the envelope and sample logs.","checks":["Different facts for one job have different event IDs.","Retrying the same fact preserves its event ID and consumer scope."],"solution":"Use job j-4 with event e-17 for ExportRequested and a different stable event ID for ExportCompleted. Repeated e-17 delivery is suppressed within the same consumer, while the new completion fact is retained. Correlation links both facts to the original request; it is not the deduplication key.","solutionFormat":"prose"}},{"id":"acceptance","title":"4. Publish confirmation versus completion","takeaway":"Publisher confirmation reports broker acceptance; consumer acknowledgement reports that the consumer finished handling a delivery.","sections":[{"title":"Publisher confirms and acknowledgements","paragraphs":["A publisher confirm tells the sender about broker acceptance under configured broker semantics. A consumer acknowledgement tells the broker a delivery was handled. Neither automatically tells the original browser that its export is complete. The producer can lose a confirm even when the broker accepted the message, so retry must tolerate uncertainty and duplicates."]},{"title":"Lost confirmation and duplicate publication","paragraphs":["Suppose the broker accepts e-17, then the producer connection drops before its confirm arrives. The sender cannot distinguish this from non-acceptance. Republishing the same e-17 is reasonable with deduplication. The export worker must commit its own effect before acknowledging; receipt alone is insufficient."]}],"quiz":{"question":"Publisher confirmation reports broker acceptance; consumer acknowledgement reports that the consumer finished handling a delivery. Which decision follows?","options":["Retry uncertain publication with stable identity and durable consumer handling.","Assume a missing confirmation proves the broker did not receive it.","Interpret the publisher confirm as confirmation that all subscribers completed their effects."],"correct":0,"explanation":"A missing reply leaves an uncertain outcome; confirmations and acknowledgements describe separate relationships."},"references":[{"title":"RabbitMQ acknowledgements and confirms","url":"https://www.rabbitmq.com/docs/confirms","section":"Consumer acknowledgements; publisher confirms; prefetch","reviewed":"2026-09-30","scope":"Core SQLite exercises are protocol-neutral. The optional broker_ack_drill.py uses a real local RabbitMQ/Pika connection for channel-loss redelivery; it does not test broker restart or replication."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"foundation","exercise":{"prompt":"Draw three crash windows: before broker acceptance, after acceptance before confirm, and after consumer commit before acknowledgement. State what each participant knows at that point.","checks":["Describe the uncertainty caused by a lost publisher confirm.","Place consumer acknowledgement after the durable effect and explain duplicate handling."],"solution":"Before broker acceptance the sender lacks a confirmed delivery. After acceptance with a lost confirm the sender cannot distinguish accepted from absent and retries the stable ID. After consumer commit with a lost acknowledgement replay must consult the durable inbox. Only the consumer owns knowledge of its committed effect.","solutionFormat":"prose"},"diagram":{"title":"Two acknowledgements, two boundaries","summary":"Acceptance is distinct from business completion.","nodes":[{"id":"0","label":"Producer","description":"Keeps stable event ID on uncertain retry."},{"id":"1","label":"Broker","description":"Acceptance depends on configured broker semantics."},{"id":"2","label":"Consumer","description":"Commits local effect before acknowledging."}],"edges":[{"from":"0","to":"1","label":"publish"},{"from":"1","to":"0","label":"publisher confirm"},{"from":"1","to":"2","label":"deliver"},{"from":"2","to":"1","label":"consumer ack after commit"}],"steps":[{"title":"1. publish","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Acceptance depends on configured broker semantics."},{"title":"2. publisher confirm","activeNodes":["1","0"],"activeEdges":[1],"explanation":"Keeps stable event ID on uncertain retry."},{"title":"3. deliver","activeNodes":["1","2"],"activeEdges":[2],"explanation":"Commits local effect before acknowledging."},{"title":"4. consumer ack after commit","activeNodes":["2","1"],"activeEdges":[3],"explanation":"Acceptance depends on configured broker semantics."}],"type":"sequence","sequenceOrder":[0,1,2,3]}},{"id":"delivery-semantics","title":"5. Delivery guarantees and effect boundaries","takeaway":"At-least-once delivery demands duplicate-safe effects.","sections":[{"title":"Delivery versus business effects","paragraphs":["At-most-once processing can lose work when acknowledgement precedes the effect. At-least-once delivery permits retries and duplicate deliveries. Exactly-once claims must state their boundary: a broker or stream transaction is not automatically an exactly-once email, payment or external API call. Local atomic transactions can make one database effect effectively once for a stable key."]},{"title":"Atomic SQLite effects","paragraphs":["The practice lab commits an inbox row and projection update together in SQLite. A replay sees the inbox key and avoids a second projection update. An external email sent between those statements would fall outside SQLite rollback; it needs a provider idempotency key or reconciliation strategy."]}],"quiz":{"question":"At-least-once delivery demands duplicate-safe effects. Which decision follows?","options":["Describe which local effect is deduplicated and which external effect remains uncertain.","Label the whole workflow exactly once because it has an inbox table.","Rely on broker exactly-once delivery to eliminate duplicate calls to any external payment API."],"correct":0,"explanation":"A guarantee is only meaningful inside the mechanism that enforces it."},"references":[{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."},{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."}],"stage":"foundation","exercise":{"prompt":"Run the duplicate test. Then propose how an email provider without idempotency would be handled.","checks":["Scope the proven guarantee to the local database effect.","Identify an external-email uncertainty and a reconciliation strategy."],"solution":"The SQLite inbox/projection transaction establishes one committed local effect per consumer/event key across repeated delivery. Sending an email is outside that transaction. Use a provider idempotency key or retained receipts and reconciliation; if those are unavailable, preserve the uncertain state and acknowledge that duplicates cannot be eliminated by the local inbox alone.","solutionFormat":"prose"}},{"id":"consumer-lifecycle","title":"6. Receive, commit and acknowledge","takeaway":"Acknowledge only after durable work succeeds.","sections":[{"title":"Receive, commit and acknowledge","paragraphs":["A worker receives a delivery, validates it, performs durable work, commits, and then acknowledges. If its channel closes before acknowledgement, brokers can redeliver. Delivery tags may be channel-scoped, while application event IDs survive channels. These identifiers must not be substituted for each other."]},{"title":"Crash windows","paragraphs":["Crash before commit: database changes roll back and replay must do the work. Crash after commit before acknowledgement: replay must detect the committed inbox entry and skip the effect. The lab injects a failure during a transaction to prove both inbox and projection remain unchanged."]},{"title":"Reproduce the commit-to-ack gap against a broker","paragraphs":["An event adds 7 to a balance. The consumer inserts event-1 into its inbox and updates the balance in one transaction, then its channel closes before acknowledgement. RabbitMQ redelivers the unacknowledged delivery. On replay the inbox key already exists, so the transaction skips the balance increment and the consumer acknowledges on the new channel. The two deliveries share an application ID; their channel delivery tags need not match.","broker_ack_drill.py exercises that transport boundary with a real optional local RabbitMQ server. It closes the first connection deliberately and verifies redelivered plus balance=7 on the second. Its in-memory SQLite database stays alive in the same Python process, so the drill demonstrates channel loss, not process-crash persistence. The existing file-backed inbox tests address local durable state separately.","Read this as a transport preview now. Implement the inbox in lesson 9 before attempting mechanism-lab.md; the local foundation project needs no broker installation."],"example":"first delivery: inbox inserts event-1; balance 0 -> 7; commit\nconnection closes before ack\nredelivery: inbox conflict; balance stays 7; ack on new channel","exampleFormat":"prose"}],"quiz":{"question":"Acknowledge only after durable work succeeds. Which decision follows?","options":["Commit inbox and effect together, then acknowledge at the transport boundary.","Insert the inbox marker first in a separate committed transaction.","Acknowledge before the transaction commits to reduce the chance of duplicate delivery."],"correct":0,"explanation":"A separate inbox commit can suppress replay even when the business effect never committed."},"references":[{"title":"RabbitMQ acknowledgements and confirms","url":"https://www.rabbitmq.com/docs/confirms","section":"Consumer acknowledgements; publisher confirms; prefetch","reviewed":"2026-09-30","scope":"Core SQLite exercises are protocol-neutral. The optional broker_ack_drill.py uses a real local RabbitMQ/Pika connection for channel-loss redelivery; it does not test broker restart or replication."},{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."},{"title":"Pika blocking channel operations","url":"https://pika.readthedocs.io/en/stable/modules/adapters/blocking.html","section":"basic_get, basic_ack and publisher confirmation","reviewed":"2026-10-02","scope":"Primary API documentation for the optional mechanism lab. Runtime prerequisites and execution evidence are separate in mechanism-lab.md."}],"stage":"foundation","exercise":{"prompt":"Event e-17 adds 7. Its first delivery commits, then acknowledgement is lost. Predict the balance after redelivery with a remembered event ID and with an unconditional increment. Explain why acknowledging before commit creates a different failure. You can trace this on paper; the optional broker drill belongs after the inbox lesson.","checks":["Predict balance 7 with duplicate detection and 14 with an unconditional second increment.","Explain how an acknowledgement before commit can lose the effect if the worker crashes."],"solution":"The duplicate business effect is balance=14, even though both deliveries carried one event ID. Restore the inbox/effect transaction and acknowledge after it commits. Early acknowledgement hides redelivery by accepting a loss window; it does not provide exactly-once effects.","solutionFormat":"prose"},"diagram":{"title":"Commit before acknowledgement","summary":"Replay after a lost acknowledgement detects the durable inbox.","nodes":[{"id":"0","label":"Delivery","description":"Validate stable ID and schema."},{"id":"1","label":"Already committed?","description":"Look up consumer/event unique key.","shape":"decision"},{"id":"2","label":"Commit inbox + projection","description":"Atomic SQLite transaction.","shape":"database"},{"id":"3","label":"Acknowledge","description":"After a known local commit; duplicates skip repeated effect.","shape":"terminal"}],"edges":[{"from":"0","to":"1","label":"validate"},{"from":"1","to":"2","label":"no: do work"},{"from":"2","to":"3","label":"commit succeeded"},{"from":"1","to":"3","label":"yes: skip effect"}],"steps":[{"title":"1. validate","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Look up consumer/event unique key."},{"title":"2. no: do work","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Atomic SQLite transaction."},{"title":"3. commit succeeded","activeNodes":["2","3"],"activeEdges":[2],"explanation":"After a known local commit; duplicates skip repeated effect."},{"title":"4. yes: skip effect","activeNodes":["1","3"],"activeEdges":[3],"explanation":"After a known local commit; duplicates skip repeated effect."}],"direction":"LR"}},{"id":"durability","title":"7. Durability and queue lifetime","takeaway":"Persistence, replication and retention are separate decisions.","sections":[{"title":"Queue and message lifetime","paragraphs":["A durable queue definition, persistent message flag, publisher confirm and replicated broker storage protect different failure windows. Temporary or exclusive queue lifetimes may remove queues when connections end. No single adjective guarantees survival of host loss, operator deletion or expired retention. Consumer acknowledgements do not back up the broker."]},{"title":"Retention and disk-failure limits","paragraphs":["An export request must survive worker restart, but a transient UI notification may be disposable. Record retention and maximum queue age explicitly. The SQLite lab is durable on one file-backed database but does not simulate a replicated broker or prove disk-failure survival."]}],"quiz":{"question":"Persistence, replication and retention are separate decisions. Which decision follows?","options":["Test the specific failure mode behind a durability claim.","Assume a persistent flag survives every failure and operator action.","Treat replicated broker storage as a replacement for separately protected deletion recovery."],"correct":0,"explanation":"Durability is a combination of configured storage behavior and independently tested recovery."},"references":[{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"foundation","exercise":{"prompt":"Write a failure matrix for process restart, host loss and accidental deletion. For each, name the actual protection and a recovery test. Do not mark the lab test as evidence for replication.","checks":["Name different protections for process restart, host loss and deletion.","Mark replicated broker and backup claims as requiring real experiments."],"solution":"Process restart requires durable local state and broker definitions/messages appropriate to the product. Host loss may also require replicated durable storage and a tested failover path. Operator deletion needs separately protected backup/recovery and ownership controls. The local SQLite suite does not test broker replication or recovery after deletion.","solutionFormat":"prose"}},{"id":"routing","title":"8. Routing and subscription ownership","takeaway":"Routes must express ownership and isolate subscriber failures.","sections":[{"title":"Routing and subscriber ownership","paragraphs":["Route by a documented event type or routing key. Avoid routing directly from untrusted arbitrary strings. Give each logical subscriber a separately owned delivery history, retry budget and retention policy. A catch-all subscription is useful for an audit reader but can become an accidental source of sensitive data exposure."]},{"title":"Independent audit and notification","paragraphs":["ExportCompleted feeds audit and notifications. If notifications are down, audit can continue because the subscriptions are independent. Adding two notification workers to that subscription improves throughput without duplicating its logical responsibility. A schema name should be stable even when service deployment names change."]}],"quiz":{"question":"Routes must express ownership and isolate subscriber failures. Which decision follows?","options":["Define routes, independent subscription ownership and unroutable-message evidence.","Use a service hostname as the permanent business event type.","Give every subscriber a catch-all route to avoid maintaining routing contracts."],"correct":0,"explanation":"Business contracts should survive topology changes and failures should be visible to an owner."},"references":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"Azure competing consumers","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/competing-consumers","section":"Solution; issues and considerations","reviewed":"2026-09-30","scope":"Logical queue consumer pattern; not a guarantee for every broker."}],"stage":"foundation","exercise":{"prompt":"List three event types and authorized subscribers. Explain what happens to an unroutable event and how a publisher observes that condition in the selected broker; do not silently discard a business-critical message.","checks":["List allowed event-type/subscriber pairs.","State how the chosen broker exposes an unroutable critical message."],"solution":"Use ExportRequested for the authorized export worker and ExportCompleted for independent audit and notification subscribers. Document routing keys, subscriber owners and retry/retention policies. An unroutable critical event needs a visible return/error or equivalent broker-specific observation; it cannot silently disappear while the UI reports success.","solutionFormat":"prose"}},{"id":"idempotent-consumers","title":"9. Durable inbox and idempotency","takeaway":"Deduplication must survive restarts and be scoped to each consumer.","sections":[{"title":"Inbox keys and atomic updates","paragraphs":["An inbox uses a unique key such as consumer name plus event ID. Combine insert-or-detect with the business update in one transaction. An in-memory set disappears on restart and cannot coordinate multiple processes. Retention of inbox keys must cover expected redelivery and replay windows; pruning too early permits effects again."]},{"title":"Replay and payload collisions","paragraphs":["Audit and notifications can each process e-17 once, so their inbox keys differ. The lab consumes an event into a SQL projection and counts the effect once across repeated delivery and reopened connections. It rejects reuse of an ID with a different job/value payload instead of pretending that a collision is a valid replay."],"example":"from contextlib import closing\nfrom event_lab import connect, create_job, consume, total\n\nwith closing(connect(':memory:')) as db:\n    event = create_job(db, 'j-4', 'e-17', 7)\n    print(consume(db, 'audit', event))  # True\n    print(consume(db, 'audit', event))  # False\n    print(total(db, 'audit', 'j-4'))   # 7"}],"quiz":{"question":"Deduplication must survive restarts and be scoped to each consumer. Which decision follows?","options":["Use a durable unique key and atomic effect, with an explicit retention window.","Keep only the last ten IDs in worker memory.","Deduplicate all subscribers using one global event-ID row, preventing other subscribers from processing it."],"correct":0,"explanation":"Restart, concurrency and replay all require durable deduplication beyond a short process-local history."},"references":[{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"intermediate","exercise":{"prompt":"Run duplicate and identity-collision tests. Design a retention rule if events can replay for thirty days, and identify what happens after keys expire. The reference keeps keys indefinitely only because the training dataset is small.","checks":["Verify duplicate and reopen tests preserve one local effect.","State what can happen after a deduplication key is pruned."],"solution":"The unique inbox key combines consumer and event identity and commits with its effect. Separate consumers can each process the same fact. Retain keys for at least the promised redelivery/replay window plus an explicit margin; after expiry a replay may apply again. Identity collisions with changed content fail rather than masquerading as duplicates.","solutionFormat":"prose"}},{"id":"transactional-outbox","title":"10. Transactional outbox","takeaway":"Write the business change and pending event in one local transaction.","sections":[{"title":"The dual-write gap","paragraphs":["A database update followed by a separate publish is a dual write. A crash between them leaves a committed business change without its event. Reversing the order can publish a fact whose business transaction later fails. An outbox stores the business change and publication record in one transaction; a relay later publishes pending records."]},{"title":"Relay retries after publication","paragraphs":["create_job() inserts job j-4 and outbox event e-17 together. The relay can crash after sending but before marking sent, so it must retry and may duplicate publication. The outbox closes the local commit gap but does not remove the consumer duplicate problem."],"example":"from contextlib import closing\nfrom event_lab import connect, create_job, pending\n\nwith closing(connect(':memory:')) as db:\n    create_job(db, 'j-4', 'e-17', 7)\n    print(len(pending(db)))  # 1 committed pending event"},{"title":"Which crash leaves which durable evidence?","paragraphs":["There are three different boundaries. Before the producer transaction commits, neither business row nor outbox row should survive. After it commits but before publish, the pending outbox row allows recovery. After confirmed publication but before the sent marker commits, the relay cannot prove the marker survived and retries the same event ID. This last case permits duplicate delivery by design.","Deleting or marking the row before publication eliminates the retry evidence and can lose the event. Holding a database transaction open across a network publish does not create one atomic broker/database commit: the broker can accept just before the database rolls back. Keep the relay transaction short, reuse a stable event ID and let the consumer transaction enforce one local effect."],"example":"producer rollback -> no job, no event\nproducer commit + relay unavailable -> job + pending event\npublish accepted + sent mark lost -> retry same event ID\nconsumer replay -> inbox prevents a second effect","exampleFormat":"prose"}],"quiz":{"question":"Write the business change and pending event in one local transaction. Which decision follows?","options":["Commit business data and outbox atomically; deduplicate eventual deliveries.","Mark the outbox sent before attempting publication.","Delete the outbox row immediately after starting an asynchronous publish call."],"correct":0,"explanation":"An outbox prevents lost intent at a local boundary; relay uncertainty remains and demands duplicate-safe consumers."},"references":[{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."},{"title":"RabbitMQ acknowledgements and confirms","url":"https://www.rabbitmq.com/docs/confirms","section":"Consumer acknowledgements; publisher confirms; prefetch","reviewed":"2026-09-30","scope":"Core SQLite exercises are protocol-neutral. The optional broker_ack_drill.py uses a real local RabbitMQ/Pika connection for channel-loss redelivery; it does not test broker restart or replication."}],"stage":"intermediate","exercise":{"prompt":"A relay receives publisher confirmation and crashes before marking the outbox row sent. On restart it publishes again. Is that evidence that the outbox failed? Give the final inbox and balance results for event-1 adding 7.","checks":["The pending outbox row causes a retry with the same event ID; publication can occur twice.","A correct consumer ends with one inbox row and balance=7, not 14."],"solution":"This is the expected uncertainty window. The outbox preserves publication intent, not unique delivery. Retrying the same ID and atomically deduplicating the consumer effect yields one inbox row and balance 7. Generating a new event ID for each relay attempt defeats that protection.","solutionFormat":"prose"},"diagram":{"title":"One local commit, uncertain relay","summary":"An outbox prevents local dual-write loss; consumer deduplication handles relay replay.","nodes":[{"id":"0","label":"Business transaction","description":"Writes job and pending event atomically.","shape":"database"},{"id":"1","label":"Outbox relay","description":"Reads committed pending events."},{"id":"2","label":"Broker","description":"Accepts a published event; lost reply can cause retry."},{"id":"3","label":"Consumer inbox + effect","description":"Commits dedupe key and projection together.","shape":"database"}],"edges":[{"from":"0","to":"1","label":"committed intent"},{"from":"1","to":"2","label":"publish stable ID"},{"from":"2","to":"3","label":"possible repeated delivery"}],"steps":[{"title":"1. committed intent","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Reads committed pending events."},{"title":"2. publish stable ID","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Accepts a published event; lost reply can cause retry."},{"title":"3. possible repeated delivery","activeNodes":["2","3"],"activeEdges":[2],"explanation":"Commits dedupe key and projection together."}],"direction":"LR"}},{"id":"retry-budget","title":"11. Bounded retries and poison messages","takeaway":"Retry transient failures without creating an endless hot loop.","sections":[{"title":"Retry classes and budgets","paragraphs":["Classify retryable dependency failures separately from malformed messages and permanent authorization failures. Backoff spreads attempts; jitter reduces synchronized bursts. Limit attempts or total elapsed time and move exhausted work to quarantine with its original ID, failure reason and attempt count. Do not keep immediately requeuing an invalid payload forever."]},{"title":"Waits versus job expiry","paragraphs":["With attempt delays of 1, 2 and 4 seconds, three retry waits total 7 seconds before considering handler time. If a job expires after 5 seconds, that schedule already exceeds its usefulness. The lab models retry classification deterministically rather than sleeping or invoking a real broker."],"example":"from event_lab import retry_decision\n\nfor attempt in (1, 2, 3):\n    print(retry_decision(attempt, True))\n# retry delay 1; retry delay 2; quarantine delay 0\nprint(retry_decision(1, False))  # permanent: quarantine"}],"quiz":{"question":"Retry transient failures without creating an endless hot loop. Which decision follows?","options":["Classify failure and cap retry work by attempts and usefulness deadline.","Retry every failure forever because eventual delivery is desirable.","Reset the attempt counter on each reconnect so transient jobs eventually always succeed."],"correct":0,"explanation":"Permanent payload errors are not repaired by repetition, and transient failures still consume finite capacity."},"references":[{"title":"RabbitMQ dead-letter exchanges","url":"https://www.rabbitmq.com/docs/dlx","section":"What is a dead letter exchange; configuring; safety","reviewed":"2026-10-02","scope":"RabbitMQ dead-letter routing. The local retry classifier returns a quarantine decision; it does not persist a quarantine table or transfer messages."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"intermediate","exercise":{"prompt":"Use retry_decision() with attempt counts 1 through 4. Decide whether a missing required field should ever retry unchanged. Explain your classification and retry budget.","checks":["Separate permanent input failure from transient dependency failure.","Record the exact reference decisions and distinguish classification from scheduling."],"solution":"An invalid required field will not become valid if the payload stays unchanged. Quarantine the message immediately. A transient dependency failure gets bounded attempts and usefulness deadlines; the reference returns retry delays 1 and 2 for attempts 1 and 2, then quarantine at attempt 3. Timed execution and persistence are not implemented by this classifier.","solutionFormat":"prose"}},{"id":"dead-letter-replay","title":"12. Quarantine and controlled replay","takeaway":"A dead-letter store needs an owner and a repair workflow.","sections":[{"title":"Quarantine ownership and replay","paragraphs":["A dead-letter queue is a holding area, not an automatic fix. Preserve original identity and failure details, restrict access, alert on age and growth, and define who repairs the producer or consumer. Blindly copying messages back can recreate an outage. Broker dead-letter transfer has its own durability and configuration limits."]},{"title":"Repairing a version mismatch","paragraphs":["A version-2 payload reaches a version-1-only consumer and is quarantined. First deploy a compatible consumer and run a sample in isolation. Then replay a bounded batch while checking duplicates and side effects. Do not edit the event ID merely to bypass inbox handling."]}],"quiz":{"question":"A dead-letter store needs an owner and a repair workflow. Which decision follows?","options":["Repair the cause and replay a bounded observable batch.","Clear the dead-letter queue to make the alert green.","Assign new IDs to dead-lettered messages so old inbox entries cannot block replay."],"correct":0,"explanation":"Moving or deleting messages does not establish completed business work or prevent recurrence."},"references":[{"title":"RabbitMQ dead-letter exchanges","url":"https://www.rabbitmq.com/docs/dlx","section":"What is a dead letter exchange; configuring; safety","reviewed":"2026-10-02","scope":"RabbitMQ dead-letter routing. The local retry classifier returns a quarantine decision; it does not persist a quarantine table or transfer messages."}],"stage":"intermediate","exercise":{"prompt":"In workbook.md write a replay approval checklist: cause corrected, payload access authorized, dry sample checked, batch bounded, metrics watched, stop trigger defined. Explain what evidence marks a message repaired versus simply moved.","checks":["Preserve original IDs and error evidence during replay.","Define a repair criterion and a batch stop trigger."],"solution":"Repair the compatibility failure before replaying. Check authorized payload access, validate a sample, preserve event identity, bound batch size and monitor outcomes and stop criteria. Mark repaired only when the required effect and deduplication behavior are verified; merely moving the record is not a business completion.","solutionFormat":"prose"},"diagram":{"title":"Repair before replay","summary":"A quarantine store preserves evidence; replay is bounded and observable.","nodes":[{"id":"0","label":"Failure","description":"Record ID, attempts and error."},{"id":"1","label":"Retry useful?","description":"Classify transient error and deadline.","shape":"decision"},{"id":"2","label":"Finite retry","description":"Apply backoff under the budget."},{"id":"3","label":"Quarantine","description":"Retain failure evidence.","shape":"database"},{"id":"4","label":"Controlled replay","description":"Repair cause, test sample, watch stop criteria."}],"edges":[{"from":"0","to":"1","label":"classify"},{"from":"1","to":"2","label":"yes"},{"from":"1","to":"3","label":"no"},{"from":"3","to":"4","label":"owner repairs and reviews"}],"steps":[{"title":"1. classify","activeNodes":["0","1"],"activeEdges":[0],"explanation":"Classify transient error and deadline."},{"title":"2. yes","activeNodes":["1","2"],"activeEdges":[1],"explanation":"Apply backoff under the budget."},{"title":"3. no","activeNodes":["1","3"],"activeEdges":[2],"explanation":"Retain failure evidence."},{"title":"4. owner repairs and reviews","activeNodes":["3","4"],"activeEdges":[3],"explanation":"Repair cause, test sample, watch stop criteria."}],"direction":"LR"}},{"id":"ordering","title":"13. Ordering, keys and stale events","takeaway":"Ordering is scoped and consumers must detect stale changes.","sections":[{"title":"Scoped order and stale versions","paragraphs":["Partition or session keys can serialize related work within a selected scope, but not across all entities or subscribers. Concurrent workers and retries can alter completion order even if delivery order was FIFO. A version number lets a projection detect missing or stale changes. A timestamp alone is weaker because clocks can disagree."]},{"title":"Last-value versus ledger projections","paragraphs":["Progress version 4 arrives before version 3. A last-value projection can ignore the stale version if its contract allows that; an incrementing ledger cannot simply drop version 3. State transitions may require buffering or querying authoritative state to close gaps."]}],"quiz":{"question":"Ordering is scoped and consumers must detect stale changes. Which decision follows?","options":["Choose the aggregate ordering scope and explicitly handle gaps or stale versions.","Assume a queue name guarantees global business completion order.","Sort by wall-clock timestamp and infer a total order across every producer."],"correct":0,"explanation":"Delivery, processing completion and application state order are separate and need scoped contracts."},"references":[{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."},{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."}],"stage":"intermediate","exercise":{"prompt":"Compare two aggregates A and B: A1, B1, A2, B2. Which order matters within each aggregate, and which can be parallel? State why changing the partition count can require careful ordering assumptions.","checks":["Distinguish per-aggregate order from cross-aggregate concurrency.","Explain a gap/stale policy appropriate to a state projection versus a ledger."],"solution":"A1 before A2 and B1 before B2 are per-aggregate constraints; A and B can usually process concurrently. Arrival and completion ordering differ under retry or multiple workers. Version checks can detect gaps/stale state, but increment ledgers cannot arbitrarily discard an earlier operation. Partition changes require reviewing how keys remain consistently ordered.","solutionFormat":"prose"}},{"id":"schemas","title":"14. Schema evolution and compatibility","takeaway":"Deploy producers and consumers independently with compatible contracts.","sections":[{"title":"Serializer compatibility","paragraphs":["An additive optional field is often easier to evolve than a renamed required field. Compatibility depends on actual serializer behavior: some readers reject unknown fields, some supply defaults, and some silently coerce types. Specify schema version, validation and deprecation windows; test old/new payloads against both supported consumers."]},{"title":"An additive field and an ID change","paragraphs":["Add display_name to ExportCompleted while retaining job_id and event_id. Old consumers should still work if their parser accepts additional fields. Changing job_id from a string to an integer can break deduplication and needs a deliberate migration, not just a new producer deployment."],"example":"from event_lab import validate\n\nevent = {'id': 'e-17', 'job_id': 'j-4',\n         'type': 'ExportRequested', 'version': 1, 'value': 7}\nprint(validate(event))  # canonical JSON for this local Python reference\n# validate(event | {'display_name': 'Example'}) raises ValueError:\n# the supplied v1 parser deliberately rejects unknown fields."}],"quiz":{"question":"Deploy producers and consumers independently with compatible contracts. Which decision follows?","options":["Test a compatibility matrix and retain stable identity semantics.","Assume every added field is automatically backward compatible.","Rename required identifiers and rely on consumers to infer the old names."],"correct":0,"explanation":"Compatibility is determined by real reader behavior and identity contracts, not just whether a JSON field was added."},"references":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"CloudEvents specification","url":"https://cloudevents.io/","section":"Specification; context attributes","reviewed":"2026-09-30","scope":"CloudEvents standard landing page; teaching envelopes are inspired by its vocabulary, not claimed as a conformant transport implementation."}],"stage":"intermediate","exercise":{"prompt":"Create a compatibility matrix with producer v1/v2 and consumer v1/v2. Add a malformed payload and confirm it is quarantined rather than coerced. Keep producer schema tests separate from transport delivery tests.","checks":["Include all four supported-version combinations.","Show that the supplied strict parser needs an explicit change for optional fields."],"solution":"Test all producer-v1/v2 and consumer-v1/v2 combinations actually supported. Retain job/event identity types. Quarantine a malformed payload rather than changing its values to make it pass validation. The supplied strict v1 parser rejects unknown fields, so adding display_name requires a parser/contract change and tests before its producer is released.","solutionFormat":"prose"}},{"id":"backpressure","title":"15. Backpressure, prefetch and backlog","takeaway":"Bound in-flight work and measure queue age.","sections":[{"title":"Outstanding deliveries and capacity","paragraphs":["Prefetch limits outstanding unacknowledged deliveries for relevant broker consumers. It is not a complete memory or request-rate limit. Worker concurrency, payload size and downstream capacity also matter. A queue absorbs a temporary mismatch but cannot solve a permanent arrival rate above processing capacity. Oldest-message age often communicates user delay more clearly than depth alone."]},{"title":"Backlog growth and drain time","paragraphs":["If arrivals are 120 jobs/s and workers complete 100/s for 60 seconds, backlog grows by 1,200 jobs. With arrivals later at 80/s, net drain is 20/s and ideal drain time is 60 seconds. These deterministic estimates ignore variable service time and retries."],"example":"arrival_rate, service_rate, burst_seconds = 120, 100, 60\nbacklog = (arrival_rate - service_rate) * burst_seconds\nsteady_arrivals = 80\nprint(backlog)  # 1200\nprint(backlog / (service_rate - steady_arrivals))  # 60.0 seconds"}],"quiz":{"question":"Bound in-flight work and measure queue age. Which decision follows?","options":["Limit concurrency and admit work from measured capacity and age.","Increase queue capacity and claim the system now handles unlimited load.","Raise prefetch without limit whenever the queue grows, because fetching more messages increases downstream capacity."],"correct":0,"explanation":"Storage delays overload consequences; it does not raise sustainable processing throughput."},"references":[{"title":"RabbitMQ acknowledgements and confirms","url":"https://www.rabbitmq.com/docs/confirms","section":"Consumer acknowledgements; publisher confirms; prefetch","reviewed":"2026-09-30","scope":"Core SQLite exercises are protocol-neutral. The optional broker_ack_drill.py uses a real local RabbitMQ/Pika connection for channel-loss redelivery; it does not test broker restart or replication."},{"title":"Azure competing consumers","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/competing-consumers","section":"Solution; issues and considerations","reviewed":"2026-09-30","scope":"Logical queue consumer pattern; not a guarantee for every broker."}],"stage":"intermediate","exercise":{"prompt":"Calculate drain time for the 1,200-job backlog when arrivals fall to 95/s and processing stays at 100/s. Define an admission policy when queue age approaches the export expiry. Compare rejecting new work with accepting work that will inevitably expire.","checks":["Compute 1200 divided by 5 as 240 seconds.","Name a queue-age admission or stop policy and its capacity assumptions."],"solution":"The burst adds 1200 jobs. At 95 arrivals/s and 100 completions/s, net drain is 5/s and ideal drain time is 240 seconds. Bound worker concurrency and outstanding deliveries against downstream limits. If queue age approaches expiry, reject/defer new work under an explicit policy rather than accept inevitable failure.","solutionFormat":"prose"}},{"id":"stream-replay","title":"16. Log offsets, retention and replay","takeaway":"A retained log separates stored records from consumer position.","sections":[{"title":"Partition offsets and retention","paragraphs":["A log stores records by partition and offset; each consumer group tracks progress. Committing an offset before the effect risks skipping unfinished work after restart. Committing after the effect permits replay and requires duplicate-safe effects. Retention can remove old records even if a slow consumer has not processed them."]},{"title":"Isolated projection rebuilds","paragraphs":["An analytics projection rebuilds from offset zero into a new database, then switches readers after checks. Email notifications should not be replayed into the real provider during that rebuild. Use a new projection consumer identity and disable external effects for historical processing."]}],"quiz":{"question":"A retained log separates stored records from consumer position. Which decision follows?","options":["Verify retained history and isolate side effects before rebuilding a projection.","Reset offsets and resend every historical email as part of rebuilding analytics.","Assume an uncommitted consumer offset prevents retention from deleting its unread records."],"correct":0,"explanation":"Replay is a data-processing operation whose effects must be explicitly scoped and whose history must still exist."},"references":[{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."}],"stage":"intermediate","exercise":{"prompt":"Explain how a consumer 10 days behind behaves when retention is 7 days.","checks":["Identify the missing-history interval.","Keep historical analytics rebuild isolated from real notifications."],"solution":"A consumer ten days behind a seven-day retained log cannot read already expired history. Recover from a protected snapshot or authoritative source, then reconcile the retained tail. Build the new analytics projection with a separate identity and suppressed external effects; offset reset alone cannot recover deleted records.","solutionFormat":"prose"}},{"id":"sagas","title":"17. Distributed workflow and compensation","takeaway":"A saga coordinates local transactions and recovery actions across a workflow.","sections":[{"title":"Steps and compensation","paragraphs":["When booking, charging and notification belong to different durable systems, one SQL transaction cannot roll back them all. A saga tracks steps and compensations. A refund compensates a charge but does not erase its historical occurrence or guarantee instant success. Some actions, such as sending email, have no true inverse."]},{"title":"Reconciling uncertain charges","paragraphs":["Reserve a workshop seat, charge through a provider, then confirm. If charging fails permanently, release the reservation. If charge outcome is uncertain, reconcile before issuing another charge or declaring failure. An orchestrator stores decisions durably; choreography spreads them among services and can obscure overall state."]}],"quiz":{"question":"A saga coordinates local transactions and recovery actions across a workflow. Which decision follows?","options":["Track uncertain steps and compensations as durable workflow states.","Treat compensation as an atomic rollback across all services.","Retry the entire booking saga from its first step when any reply times out."],"correct":0,"explanation":"Compensations are new fallible actions and need retries, ownership and reconciliation."},"references":[{"title":"Azure saga pattern","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/saga","section":"Solution; choreography and orchestration; considerations","reviewed":"2026-09-30","scope":"Conceptual distributed workflow guidance; compensation is not atomic rollback."}],"stage":"advanced","exercise":{"prompt":"Write a state machine with reservation expiry, payment uncertainty and failed compensation. Name the manual intervention state. Keep a local saga sketch distinct from proof that a payment provider was exercised.","checks":["Include explicit payment-uncertain and compensation-failed states.","Identify manual intervention and distinguish compensation from rollback."],"solution":"Track reservation, payment pending/uncertain, confirmed, release pending and manual-intervention states durably. Reconcile uncertain charges before charging again or releasing as failed. A permanent charge failure can trigger reservation release; failed release/refund requires an owner and retry/reconciliation. An email has no true transactional inverse.","solutionFormat":"prose"}},{"id":"security","title":"18. Messaging security and tenancy","takeaway":"Authenticate identities and authorize each messaging responsibility.","sections":[{"title":"Channel rights and trusted tenancy","paragraphs":["Limit who may publish, consume, inspect and replay each channel. Validate payload size and schema even for authenticated producers. Shared broker credentials erase attribution and widen impact. Tenant ID inside a message is data that must be checked against trusted context; it is not authorization by itself."]},{"title":"Least privilege and dead-letter privacy","paragraphs":["An export worker should not be able to publish arbitrary billing events. The audit reader may view sanitized completion metadata but not credential-bearing payloads. Dead-letter stores can retain personal data long after the originating job, so include deletion and retention policies."]}],"quiz":{"question":"Authenticate identities and authorize each messaging responsibility. Which decision follows?","options":["Grant narrow channel actions and test denied access on the actual broker.","Trust all payloads because the producer authenticated once.","Use the tenant ID inside each message as sufficient proof the producer owns that tenant."],"correct":0,"explanation":"Authentication identifies the sender; authorization and payload validation remain separate controls."},"references":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."},{"title":"RabbitMQ access control","url":"https://www.rabbitmq.com/docs/access-control","section":"Authentication and authorization","reviewed":"2026-10-02","scope":"Broker resource permissions; no live broker ACL or TLS test performed by the core SQLite suite."}],"stage":"advanced","exercise":{"prompt":"Prepare a principal/action/channel matrix with explicit denied examples. Exercise negative authorization cases on an optional real broker; local Python tests do not verify TLS, certificates or broker ACL enforcement.","checks":["Provide principal/action/channel pairs and denied examples.","Separate payload validation and tenant authorization from sender authentication."],"solution":"Grant the exporter only its request consumption and completion publication actions, audit only sanitized completion reads, and replay operators separately reviewed access. Check tenant data against trusted ownership. Plan actual broker allowed/denied tests and TLS evidence; the Python suite does not authenticate a broker principal.","solutionFormat":"prose"}},{"id":"observability","title":"19. Tracing an asynchronous workflow","takeaway":"Observe acceptance, attempts and business completion separately.","sections":[{"title":"Async signals and trace context","paragraphs":["Carry correlation and trace context without embedding secrets. Measure accepted jobs, completed jobs, failures, retries, oldest pending age and dead-letter age. A high publish rate alone can mask a stalled consumer. Logs should say which event and attempt reached which state, while avoiding full sensitive payload dumps."]},{"title":"Queue wait versus API latency","paragraphs":["An export is accepted at 10:00, retries at 10:01 and completes at 10:03. The user waits for queueing and processing as well as API acceptance. Count duplicate deliveries separately from completed exports, since another delivery need not produce another business result."]}],"quiz":{"question":"Observe acceptance, attempts and business completion separately. Which decision follows?","options":["Monitor end-to-end completion and age alongside transport counters.","Use successful publish count as the sole business health signal.","Count every redelivery as a completed job so throughput reflects broker activity."],"correct":0,"explanation":"Transport success can coexist with stalled or repeatedly failing business work."},"references":[{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"advanced","exercise":{"prompt":"Write one incident query connecting job ID, event ID and attempt. Define an alert on oldest pending age plus a runbook step; distinguish a backlog caused by unavailable workers from malformed poison messages.","checks":["Separate transport deliveries from completed business jobs.","Include queue waiting in the end-to-end duration and define an age alert."],"solution":"Correlate job ID, event ID and attempt through accepted, retried and completed states. Completion latency includes queue wait plus processing. Alert on oldest pending age and dead-letter age with an owner/runbook. Compare worker availability and error classes to distinguish unavailable capacity from poison messages.","solutionFormat":"prose"}},{"id":"failure-tests","title":"20. Failure injection and concurrency evidence","takeaway":"Reproduce crashes at specific points and check that the required rules still hold.","sections":[{"title":"Failure injection and durable state","paragraphs":["Inject failures before commit, after commit and before publication bookkeeping. Reopen the database and check what persisted. An in-memory return value does not establish durability. Duplicate and malformed-message tests do not test broker failover, cross-process leases or ordering under parallel load."]},{"title":"The local crash and replay tests","paragraphs":["The local lab verifies that a crash during consume rolls back both inbox and projection. It also deliberately relays the same outbox event twice and confirms one projection effect. This is actual SQLite transaction evidence; it is not evidence about RabbitMQ quorum failover."],"example":"python event_lab.py\npython -m unittest -v test_event_lab.py"},{"title":"Change an identity without changing the transport","paragraphs":["After the reference passes, use one event with two consumer names. Predict two inbox rows and a value of 7 in each consumer projection. Then reuse the original consumer and event ID with value 8: it must conflict, not add 8 or silently return duplicate. These cases distinguish subscription ownership, duplicate delivery and identity collision without requiring a broker."]}],"quiz":{"question":"Reproduce crashes at specific points and check that the required rules still hold. Which decision follows?","options":["Match each invariant to the actual failure boundary exercised.","Claim replicated broker reliability after a Python unit suite passes.","Inject exceptions only after acknowledgement and treat that as coverage of every crash window."],"correct":0,"explanation":"The test result covers its own implementation and fault model, so evidence must name that boundary."},"references":[{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."}],"stage":"advanced","exercise":{"prompt":"Run all tests and retain output plus runtime version. Add a learner-owned test for restart after publish-before-mark. Describe the real broker experiment needed to test connection-loss redelivery and durable queue recovery.","checks":["Assert reopened durable state, not just a return value.","Name the real connection-loss experiment still needed."],"solution":"Run the supplied suite and retain actual runtime/output. Add a replay after reopening the database between consumption and sent marking; one projection effect must remain. For a real broker, close the consumer connection before and after commit, inspect redelivery and test configured durable queue recovery. These are different execution boundaries.","solutionFormat":"prose"}},{"id":"broker-choice","title":"21. Selecting a broker and owning tradeoffs","takeaway":"Choose from required semantics and operational responsibilities.","sections":[{"title":"Broker capabilities and operations","paragraphs":["Compare routing, retained replay, ordering scope, payload limits, throughput, latency, transaction support, cost and team operations. RabbitMQ queues, Kafka retained logs and managed messaging services solve overlapping but different problems. Product names are not architecture requirements. Consider whether a database-backed job worker is sufficient before introducing a separate broker."]},{"title":"The notebook's requirements","paragraphs":["The notebook needs a small export queue, independent audit events and no historical stream analytics. A managed queue or conventional broker may fit; a partitioned log can be appropriate later if replayable event feeds become central. Capture what evidence would reverse that decision."]}],"quiz":{"question":"Choose from required semantics and operational responsibilities. Which decision follows?","options":["Choose a system from explicit contracts and a reversible decision record.","Choose the most popular broker and infer its guarantees from its name.","Choose from a published throughput headline without testing the actual payload and reliability settings."],"correct":0,"explanation":"Requirements and operational evidence determine suitability; popularity alone supplies neither."},"references":[{"title":"Azure competing consumers","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/competing-consumers","section":"Solution; issues and considerations","reviewed":"2026-09-30","scope":"Logical queue consumer pattern; not a guarantee for every broker."},{"title":"Azure publisher-subscriber","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/publisher-subscriber","section":"Solution; problems and considerations","reviewed":"2026-09-30","scope":"General asynchronous architecture; product guarantees must be checked separately."},{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."}],"stage":"advanced","exercise":{"prompt":"Write an ADR with two alternatives, required delivery boundary, failure ownership, access model and deletion rules. Avoid fabricated benchmark numbers; define a test workload instead.","checks":["Compare two alternatives against named contracts.","Include a falsifiable decision-reversal experiment."],"solution":"Write an ADR comparing a conventional or managed work queue with a retained log. State required routing, replay window, ordering scope, workload assumptions, access control and operations owner. Define a representative measured experiment that could reverse the choice; do not invent benchmark throughput or cost.","solutionFormat":"prose"}},{"id":"launch-review","title":"22. Messaging launch and recovery review","takeaway":"A complete workflow includes replay, retention and recovery ownership.","sections":[{"title":"Recovery across durable stores","paragraphs":["Before release, enumerate durable stores: business database, outbox, inbox, broker and projections. Their backups and retention may differ. A restored database can regress an inbox and allow old effects again; a restored outbox can republish work. Recovery needs an epoch or reconciliation plan and an isolated replay mode before external effects resume."]},{"title":"Retry and replay review","paragraphs":["The stage-three review package lists crash timelines, maximum retry budget, permitted replay effects and who owns dead-letter repair. It compares locally verified SQLite behavior with optional live broker experiments."]}],"quiz":{"question":"A complete workflow includes replay, retention and recovery ownership. Which decision follows?","options":["Review recovery across all stores and distinguish local tests from live evidence.","Restore one database and assume every messaging component is now consistent.","Resume relay immediately after any one database restore because event IDs were originally unique."],"correct":0,"explanation":"Independent durability timelines create recovery mismatches that require explicit reconciliation."},"references":[{"title":"Azure transactional outbox","url":"https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-out-box-cosmos","section":"Transactional outbox architecture and message processing","reviewed":"2026-09-30","scope":"The reference uses Cosmos DB; this course demonstrates the same local-transaction boundary with SQLite, not Cosmos change feed."},{"title":"RabbitMQ reliability guide","url":"https://www.rabbitmq.com/docs/reliability","section":"Acknowledgements; data safety; consumer reliability","reviewed":"2026-09-30","scope":"RabbitMQ guidance; actual durability requires broker-specific replication and persistence configuration."},{"title":"Apache Kafka design","url":"https://kafka.apache.org/41/design/design/","section":"Consumer position; delivery semantics; transactions; log compaction","reviewed":"2026-09-30","scope":"Explicit Kafka 4.1 conceptual reference, not a claim this is the newest Kafka release. No Kafka cluster is exercised."}],"stage":"advanced","exercise":{"prompt":"Complete the advanced workbook project. Simulate a restore with older inbox state on paper and explain how a payment/email effect would be reconciled. State a go/no-go trigger for queue age, duplicate effects and unresolved poison records.","checks":["Show a mismatch caused by restoring older inbox/outbox state.","State a go/no-go trigger and a recovery owner."],"solution":"Inventory business database, outbox, inbox, broker and projection recovery points. Restoring an older inbox can repeat previously committed external effects, so compare durable receipts and reconcile uncertainty before resuming relay. Define stop criteria for duplicate effects, oldest-job age and poison records; distinguish local tests from live broker evidence.","solutionFormat":"prose"}}],"stages":[{"id":"foundation","title":"Message contract map","description":"Design the notebook export workflow. State when the user sees accepted, processing, completed or failed.","exitCriteria":["Acceptance is not completion.","Every participant owns a specific responsibility.","Crash windows name what is known and uncertain."],"project":{"title":"Message contract map","brief":"Design the notebook export workflow. State when the user sees accepted, processing, completed or failed.","requirements":["Classify commands, facts and queries.","Sketch queue and independent subscriber responsibilities.","Draw three acknowledgement crash windows.","Define event, job and correlation identifiers."],"rubric":["Acceptance is not completion.","Every participant owns a specific responsibility.","Crash windows name what is known and uncertain."],"solution":"Use GenerateExport to request work; commit ExportRequested with a job; worker commits completion before acknowledging; ExportCompleted reaches independent audit and notification subscribers. Stable event IDs make uncertain delivery replay recognizable.","solutionFormat":"prose"}},{"id":"intermediate","title":"Crash-safe export projection","description":"Run the SQLite reference and extend its duplicate-safe workflow.","exitCriteria":["Restart and duplicate effects are considered.","The injected failure preserves the invariant.","External side effects remain explicitly outside the local transaction."],"project":{"title":"Crash-safe export projection","brief":"Run the SQLite reference and extend its duplicate-safe workflow.","requirements":["Execute the provided tests and record Python/SQLite versions.","Explain atomic outbox and inbox transactions.","Inject a failure before consumer commit.","Write finite retry and quarantine policies."],"rubric":["Restart and duplicate effects are considered.","The injected failure preserves the invariant.","External side effects remain explicitly outside the local transaction."],"solution":"Commit job/outbox together and relay stable IDs; commit inbox/projection together. On a post-commit pre-ack crash, replay reads the inbox and skips the effect. Invalid schema goes to quarantine; transient failure retries inside a finite usefulness budget.","solutionFormat":"prose"}},{"id":"advanced","title":"Failure-aware messaging launch","description":"Prepare a broker selection and recovery portfolio without provisioning one.","exitCriteria":["Evidence names the actual tested boundary.","Replay cannot silently repeat external effects.","Recovery has owners and go/no-go triggers."],"project":{"title":"Failure-aware messaging launch","brief":"Prepare a broker selection and recovery portfolio without provisioning one.","requirements":["Write a broker ADR and workload estimate.","Design schema compatibility, security and replay tests.","Define backlog age, dead-letter ownership and stop criteria.","Reconcile outbox/inbox/broker backup timelines."],"rubric":["Evidence names the actual tested boundary.","Replay cannot silently repeat external effects.","Recovery has owners and go/no-go triggers."],"solution":"Separate the locally proven SQLite transaction from optional real broker durability, ACL and connection-loss tests. Rebuild projections in isolated mode; reconcile uncertain external effects; inspect restored inbox/outbox histories before resuming relay.","solutionFormat":"prose"}}],"downloads":[{"title":"Complete runnable practice kit","href":"paths/messaging-events/practice-bundle.zip"}],"resources":{"folder":"messaging-events-practice","files":[{"id":"event_lab-py","href":"paths/messaging-events/practice/event_lab.py","role":"reference","description":"SQLite messaging example with duplicate detection and transactional effects"},{"id":"test_event_lab-py","href":"paths/messaging-events/practice/test_event_lab.py","role":"test","description":"Locally runnable regression tests."},{"id":"README-md","href":"paths/messaging-events/practice/README.md","role":"guide","description":"Runtime, exact commands, expected results, cleanup and execution boundaries."},{"id":"workbook-md","href":"paths/messaging-events/practice/workbook.md","role":"guide","description":"Three projects, exercises, evidence ledger and reference reasoning."},{"id":"mechanism-lab-script","href":"paths/messaging-events/practice/broker_ack_drill.py","role":"reference","description":"Optional real mechanism drill with observable assertions and bounded cleanup."},{"id":"mechanism-lab-guide","href":"paths/messaging-events/practice/mechanism-lab.md","role":"guide","description":"Exact setup, expected results, cleanup, scope and primary references for the optional mechanism drill."}],"tasks":[{"id":"foundation","title":"Message contract map","goal":"Design the notebook export workflow. State when the user sees accepted, processing, completed or failed.","fileIds":["event_lab-py","test_event_lab-py","README-md","workbook-md"],"steps":["Extract the flat files and read README.md.","Classify commands, facts and queries.","Sketch queue and independent subscriber responsibilities.","Draw three acknowledgement crash windows.","Define event, job and correlation identifiers.","Compare your findings with workbook.md and the stage rubric."],"commands":[{"label":"Run local demonstration","command":"python event_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_event_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim."]},{"id":"intermediate","title":"Crash-safe export projection","goal":"Run the SQLite reference and extend its duplicate-safe workflow.","fileIds":["event_lab-py","test_event_lab-py","README-md","workbook-md","mechanism-lab-script","mechanism-lab-guide"],"steps":["Extract the flat files and read README.md.","Execute the provided tests and record Python/SQLite versions.","Explain atomic outbox and inbox transactions.","Inject a failure before consumer commit.","Write finite retry and quarantine policies.","Compare your findings with workbook.md and the stage rubric.","Optional: read mechanism-lab.md and run the real mechanism drill if its prerequisites are available."],"commands":[{"label":"Run local demonstration","command":"python event_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_event_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."},{"label":"Optional mechanism drill (read its guide first)","command":"python broker_ack_drill.py","expected":"PASS reports broker redelivery, one inbox row, balance=7 and a drained queue. No process-crash durability claim."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim.","The optional mechanism lab has separate prerequisites and verification limits; see mechanism-lab.md."]},{"id":"advanced","title":"Failure-aware messaging launch","goal":"Prepare a broker selection and recovery portfolio without provisioning one.","fileIds":["event_lab-py","test_event_lab-py","README-md","workbook-md"],"steps":["Extract the flat files and read README.md.","Write a broker ADR and workload estimate.","Design schema compatibility, security and replay tests.","Define backlog age, dead-letter ownership and stop criteria.","Reconcile outbox/inbox/broker backup timelines.","Compare your findings with workbook.md and the stage rubric."],"commands":[{"label":"Run local demonstration","command":"python event_lab.py","expected":"Deterministic JSON teaching results; no network or external resource creation."},{"label":"Run local tests","command":"python -m unittest -v test_event_lab.py","expected":"All supplied unittest cases pass; no broker, cloud or identity provider is exercised."}],"prerequisites":[],"notes":["Python 3.11+ and standard library only.","Optional external tools are separately documented and not included in the local verification claim."]}],"lessonTasks":{"messages-events":"foundation","topologies":"foundation","envelopes":"foundation","acceptance":"foundation","delivery-semantics":"foundation","consumer-lifecycle":"foundation","durability":"foundation","routing":"foundation","idempotent-consumers":"intermediate","transactional-outbox":"intermediate","retry-budget":"intermediate","dead-letter-replay":"intermediate","ordering":"intermediate","schemas":"intermediate","backpressure":"intermediate","stream-replay":"intermediate","sagas":"advanced","security":"advanced","observability":"advanced","failure-tests":"advanced","broker-choice":"advanced","launch-review":"advanced"},"bundle":{"href":"paths/messaging-events/practice-bundle.zip"}}});
